function planLeaveBuilding(agent) {
    releaseAgentSeat(agent);
    const f = agent.currentFloor || 0;
    const prefix = [{ type: "STAND" }, { type: "ENTER_STATE", state: "LEAVING" }];
    if (f > 0 && agent.deskDoorWpName && agent.state === "AT_DESK") {
