        hudSpeedValEl.textContent = "Speed: " + Clock.timeScale + "x realtime";
    });
    speedRow.appendChild(hudSpeedValEl);
    speedRow.appendChild(speedSlider);
    panel.appendChild(speedRow);

    const occRow = document.createElement("div");
