        { type: "STAND" },
        { type: "ENTER_STATE", state: "ON_FLOOR" },
        { type: "WALK_TO_WP", floor: f, wpName: agent.deskDoorWpName }
    ].concat(planElevatorTrip(f, 0)).concat([
        { type: "WALK_TO_WP", floor: 0, wpName: spot },
        { type: "SIT", floor: 0, wpName: spot },
