        { type: "STAND" }
    ]).concat(planElevatorTrip(0, f)).concat([
        { type: "WALK_TO_WP", floor: f, wpName: agent.deskDoorWpName },
        { type: "WALK_TO_WP", floor: f, wpName: agent.deskWpName },
        { type: "SIT", floor: f, wpName: agent.deskWpName },
