    }

    buildingGroup.traverse((obj) => {
        if (obj.isMesh) obj.renderOrder = 0;
    });
    scene.add(buildingGroup);
    return { buildingGroup: buildingGroup, floors: floors, bfsPath: bfsPath };
}

