            const maxF = Math.floor(this.y / this.floorHeight + 1e-4);
            for (let f = maxF; f > this.targetFloor; f--) {
                if (this.destinations.has(f) || (canHall && this.downCalls.has(f))) {
                    this.targetFloor = f;
                    break;
                }
            }
        }
