    addNode(nodes, "hall_stand_S", 1.8, y, 2.3);
    sitTargets.hall_stand_S = { sit: false, facing: Math.PI };
    linkNodes(nodes, "hallSE", "hall_stand_S");

    return { nodes: nodes, sitTargets: sitTargets, desks: desks };
}

