        { type: "WAIT_SIM", minutes: randInt(22, 45) },
        { type: "STAND" },
        { type: "RELEASE_SEAT" }
    ]).concat(planElevatorTrip(meetFloor, f)).concat([
        { type: "WALK_TO_WP", floor: f, wpName: agent.deskDoorWpName },
